SELECT

FROM `match`
WHERE deleted = 0

    AND match_name LIKE CONCAT('%', #{query.matchName}, '%')


    AND league LIKE CONCAT('%', #{query.league}, '%')


    AND home_team LIKE CONCAT('%', #{query.homeTeam}, '%')


    AND away_team LIKE CONCAT('%', #{query.awayTeam}, '%')


    AND status = #{query.status}


    AND match_time >= #{query.startTime}


    AND match_time <= #{query.endTime}

ORDER BY match_time DESC

    LIMIT #{query.pageSize} OFFSET #{(query.pageNum - 1) * query.pageSize}

SELECT COUNT(*)
FROM `match`
WHERE deleted = 0

    AND match_name LIKE CONCAT('%', #{query.matchName}, '%')


    AND league LIKE CONCAT('%', #{query.league}, '%')


    AND home_team LIKE CONCAT('%', #{query.homeTeam}, '%')


    AND away_team LIKE CONCAT('%', #{query.awayTeam}, '%')


    AND status = #{query.status}


    AND match_time >= #{query.startTime}


    AND match_time <= #{query.endTime}

